// One candidate, derived from preserved incoming envelopes. No dynamics or ball control.
export const UPPER_BARS=Object.freeze([-1.875,-.625,.625,1.875].map((x,id)=>{const yaw=id===3?-Math.PI/4:0,down=[Math.sin(yaw),0,Math.cos(yaw)],center=[x,.23,id===3?-4.45:-4.55],a=center.map((v,i)=>v-.45*down[i]),b=center.map((v,i)=>v+.45*down[i]);return{id,center,down,a,b,radius:.035,mount:{radius:.055,height:.23,y:.12}};}));
function xAt(bar,z){return bar.a[0]+(z-bar.a[2])*(bar.b[0]-bar.a[0])/(bar.b[2]-bar.a[2]);}
export const UPPER_LANES=Object.freeze([0,1,2].map(id=>{const left=UPPER_BARS[id],right=UPPER_BARS[id+1],z=id===2?-4.45:-4.55,slope=((left.b[0]-left.a[0])/(left.b[2]-left.a[2])+(right.b[0]-right.a[0])/(right.b[2]-right.a[2]))/2,yaw=Math.atan(slope),down=[Math.sin(yaw),0,Math.cos(yaw)],center=[(xAt(left,z)+xAt(right,z))/2,.20,z],lamp=center.map((v,i)=>i===1?.055:v+.15*down[i]),label=center.map((v,i)=>i===1?.08:v-(id===2?.25:.40)*down[i]);return{id,leftBar:id,rightBar:id+1,center,yaw,down,half:[.35,.16,.08],lamp,label,commonZ:[Math.max(left.a[2],right.a[2]),Math.min(left.b[2],right.b[2])]};}));

